class _Console:
    """telnetlib-compatible wrapper around a scrapli channel (qemu serial console / monitor)."""

    def __init__(self, driver):
        self._driver = driver

    def open(self):
        self._driver.open()

    def close(self):
        self._driver.close()

    def write(self, data):
        if isinstance(data, bytes):
            data = data.decode(errors="ignore")
        self._driver.channel.write(data)

    def _read(self):
        # channel.read() blocks until timeout_transport (3600 s) when the console is silent,
        # so the timeout in read_until()/expect() is never evaluated and a missing prompt
        # hangs the bootstrap. Poll the socket first and return nothing if no data is ready.
        transport = self._driver.transport
        sock = getattr(getattr(transport, "socket", None), "sock", None)
        pending = getattr(transport, "_raw_buf", b"") or getattr(transport, "_cooked_buf", b"")
        if sock is not None and not pending:
            readable, _, _ = select.select([sock], [], [], 0.1)
            if not readable:
                return b""
        data = self._driver.channel.read()
        if data:
            # mirror console output to stdout so it shows up in docker logs
            sys.stdout.buffer.write(data)
            sys.stdout.buffer.flush()
        return data

    def read_very_eager(self):
        """Return whatever bytes are currently available (telnetlib-compatible)."""
        return self._read()

    def read_until(self, expected, timeout=None):
        """Read until the literal expected bytes are seen, or timeout (telnetlib-compatible)."""
        if isinstance(expected, str):
            expected = expected.encode()
        buf = b""
        t_end = time.time() + timeout if timeout else None
        while expected not in buf:
            data = self._read()
            buf += data
            if not data:
                time.sleep(0.1)
            if t_end and time.time() > t_end:
                break
        return buf

    def expect(self, regex_list, timeout=None):
        """Regex-match byte patterns against the stream (telnetlib.expect-compatible).

        Returns (index, match, buffer), or (-1, None, buffer) on timeout.
        """
        buf = b""
        t_end = time.time() + timeout if timeout else None
        while True:
            data = self._read()
            buf += data
            if not data:
                time.sleep(0.1)
            for i, pat in enumerate(regex_list):
                match = re.search(pat.decode(), buf.decode(errors="ignore"))
                if match:
                    return i, match, buf
            if t_end and time.time() > t_end:
                return -1, None, buf


